def remap_min_to_zero(grid):
    """The grid with its smallest nonzero color mapped to 0 and the other colors shifted one rank down."""
    s = sorted({v for row in grid for v in row} - {0})
    if not s:
        return [row[:] for row in grid]
    m = {s[0]: 0}
    for k in range(1, len(s)):
        m[s[k]] = s[k-1]
    return [[m[v] for v in row] for row in grid]


def demote_minority(grid, base=5):
    """Color base (default 5) becomes the grid's other color, and that other color becomes 0."""
    other = next(k for k in {v for row in grid for v in row} if k != base)
    return [[other if v == base else 0 for v in row] for row in grid]


def triangle_hatch(grid):
    """A 1-row input with one 2 becomes an h x h picture (h = width): a triangle of 2s
    (edges (r, m-r) and (r, m+r), r = 0..m, m = the 2's column) over diagonal hatching
    of 1s on lines c-r = m-4k (parallel to the right edge, spaced 4) filling the region
    c+r > m, c-r <= m, keeping 2s on top."""
    w = len(grid[0]); h = w; m = grid[0].index(2)
    out = [[0]*h for _ in range(h)]
    for r in range(m+1):
        out[r][m-r] = 2; out[r][m+r] = 2
    for r in range(h):
        for c in range(h):
            u, v = c-r, c+r
            if out[r][c] == 0 and u <= m and (u-m) % 4 == 0 and v >= m+1:
                out[r][c] = 1
    return out
